41	            logger.LogInformation("Pulse: loaded {Statements} statements from {SeedPath}.", statements, seedPath);
42	        }
43	
44	        var buckets = await RebuildWeekBucketsAsync(cancellationToken);
45	        logger.LogInformation("Pulse: week_buckets rebuilt with {Buckets} rows.", buckets);
46	    }
47	
48	    private async Task<int> LoadFixtureAsync(string seedPath, CancellationToken cancellationToken)
49	    {
50	        await using var transaction = await db.Database.BeginTransactionAsync(cancellationToken);
51	        var connection = db.Database.GetDbConnection();
52	
53	        var batch = new StringBuilder();
54	        var inBatch = 0;
55	        var total = 0;
56	
57	        await foreach (var statement in ReadStatementsAsync(seedPath, cancellationToken))
58	        {
59	            batch.AppendLine(statement);
60	            inBatch++;
61	            total++;
62	
63	            if (inBatch == StatementsPerBatch)
64	            {
65	                await ExecuteAsync(connection, transaction, batch.ToString(), cancellationToken);
66	                batch.Clear();
67	                inBatch = 0;
68	            }
69	        }
70	
71	        if (inBatch > 0)
72	        {
73	            await ExecuteAsync(connection, transaction, batch.ToString(), cancellationToken);
74	        }
75	
76	        await transaction.CommitAsync(cancellationToken);
77	        return total;
78	    }
79	
80	    // Streams the file; seed.sql is 2.4MB and is never held in memory whole.
81	    private static async IAsyncEnumerable<string> ReadStatementsAsync(
82	        string seedPath,
83	        [System.Runtime.CompilerServices.EnumeratorCancellation] CancellationToken cancellationToken)
84	    {
85	        using var reader = new StreamReader(seedPath, Encoding.UTF8);
86	        var pending = new StringBuilder();
87	        var lineNumber = 0;
88	        var statementStart = 0;
89	
90	        while (await reader.ReadLineAsync(cancellationToken) is { } line)
91	        {
92	            lineNumber++;
93	            var trimmed = line.Trim();
94	            if (pending.Length == 0 && (trimmed.Length == 0 || trimmed.StartsWith("--", StringComparison.Ordinal)))
95	            {
96	                continue;
97	            }
98	
99	            if (pending.Length == 0)
100	            {
101	                statementStart = lineNumber;
102	                if (!AllowedPrefixes.Any(p => trimmed.StartsWith(p, StringComparison.OrdinalIgnoreCase)))
103	                {
104	                    throw new InvalidDataException(
105	                        $"Unexpected statement at {seedPath}:{lineNumber}; only INSERTs into accounts and activity_events are allowed.");
106	                }
107	            }
108	
109	            pending.AppendLine(line);
110	            if (trimmed.EndsWith(';'))
111	            {
112	                yield return pending.ToString();
113	                pending.Clear();
114	            }
115	        }
116	
117	        if (pending.Length > 0)
118	        {
119	            throw new InvalidDataException($"Unterminated statement starting at {seedPath}:{statementStart}.");
120	        }
121	    }
