132	    private async Task<int> RebuildWeekBucketsAsync(CancellationToken cancellationToken)
133	    {
134	        // Window = global MIN/MAX(occurred_at) through the dedupe view, never the wall clock.
135	        // Scalar queries on purpose: the UTC converter reaches SqlQueryRaw<DateTime> through
136	        // DefaultTypeMapping, but NOT DateTime members of a record projection (verified in T1).
137	        const string From = " AS Value FROM " + RelayDbContext.DedupView;
138	        var eventCount = await db.Database.SqlQueryRaw<int>("SELECT COUNT(*)" + From).SingleAsync(cancellationToken);
139	        var timezones = await db.Accounts
140	            .Select(a => a.Timezone)
141	            .Distinct()
142	            .OrderBy(tz => tz)
143	            .ToListAsync(cancellationToken);
144	
145	        await using var transaction = await db.Database.BeginTransactionAsync(cancellationToken);
146	        await db.WeekBuckets.ExecuteDeleteAsync(cancellationToken);
147	
148	        if (eventCount == 0)
149	        {
150	            logger.LogWarning("Pulse: no events; week_buckets left empty.");
151	            await transaction.CommitAsync(cancellationToken);
152	            return 0;
153	        }
154	
155	        // Only now: MIN/MAX over an empty view is NULL, which a DateTime cannot hold.
156	        var windowStart = await db.Database.SqlQueryRaw<DateTime>("SELECT MIN(occurred_at)" + From).SingleAsync(cancellationToken);
157	        var windowEnd = await db.Database.SqlQueryRaw<DateTime>("SELECT MAX(occurred_at)" + From).SingleAsync(cancellationToken);
158	
159	        var buckets = timezones
160	            .SelectMany(tz => WeekBucketGenerator.Generate(tz, windowStart, windowEnd))
161	            .ToList();
162	
163	        db.WeekBuckets.AddRange(buckets);
164	        await db.SaveChangesAsync(cancellationToken);
165	        await transaction.CommitAsync(cancellationToken);
166	        db.ChangeTracker.Clear();
167	
168	        return buckets.Count;
169	    }
170	}
