16	    private static IEnumerable<WeeklyCount> Calls(string location, DateOnly week, int n, string? outcome = "connected") =>
17	        n == 0 ? [] : [new(week, location, "call_received", outcome, n), new(week, null, "call_received", outcome, n)];
18	
